// We use the Verus verification framework
use vstd::prelude::*;
verus! {

    // Specification function: true exactly when n is divisible by 2
    spec fn is_even(n: u32) -> bool {
        n % 2 == 0
    }

    // Executable version of is_even, with a post‐condition tying it to the spec
    fn is_even_exec(n: u32) -> bool {
        n % 2 == 0
    } ensures
        is_even_exec(n) == is_even(n);

    // Returns true iff there exists an index i in [0, arr.len())
    // such that arr[i] is even.  On empty arr, returns false.
    fn is_product_even(arr: &Vec<u32>) -> bool
        ensures
            // result ↔ ∃ i < arr.len(). is_even(arr[i])
            result == exists |i: nat| i < arr@.len && is_even(arr@[i])
    {
        let mut i: usize = 0;
        let mut found: bool = false;

        // We scan linearly; 'found' tracks whether we've seen an even yet.
        while i < arr.len() {
            invariant
                // i never exceeds arr.len()
                i <= arr.len(),
                // found ↔ ∃ k < i. arr[k] is even
                found == exists |k: nat| k < i && is_even(arr@[k]);
            decreases arr.len() - i;
            {
                if is_even_exec(arr[i]) {
                    found = true;
                }
                i += 1;
            }
        }

        found
    }
}